children.text:
.flexbox {
  border: 1px dashed blue;
  height: 200px;
  width: 320px;
  font-size: 10px;
  line-height: 10px;
}

.flexbox > div {
  width: 40px;
  float: left;
}

.big {
  height: 100px;
  font-size: 20px;
  line-height: 20px;
}

/* Classes for each of the various align-self values */
.flex-start {
  background: lime;
}
.flex-end {
  background: orange;
}
.start {
  background: lightblue;
}
.end {
  background: teal;
}
